import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

import { isUnauthenticatedAuthError } from "@/lib/auth-errors";
import type { ActionState } from "@/lib/action-state";
import { createServerSupabaseClient } from "@/lib/supabase/server";
import { guestProfileSchema } from "./schemas";

function getSaveError(code: string | undefined): string {
  if (code === "42501") {
    return "Profile saving is unavailable until the guest profile permissions migration has been applied.";
  }

  if (code === "23505") {
    return "A profile for your account already exists. Refresh the page and try again.";
  }

  return "We couldn't save your profile. Please try again.";
}

export async function saveProfileAction(
  _previousState: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const parsedValues = guestProfileSchema.safeParse({
    fullName: formData.get("fullName"),
    nationality: formData.get("nationality"),
    nationalID: formData.get("nationalID"),
    countryFlag: formData.get("countryFlag"),
  });

  if (!parsedValues.success) {
    return {
      error: "Complete each field using the allowed length, then try again.",
    };
  }

  const values = parsedValues.data;
  const supabase = await createServerSupabaseClient();
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError && isUnauthenticatedAuthError(authError)) {
    redirect("/login?next=%2Faccount%2Fprofile");
  }

  if (authError) {
    throw authError;
  }

  if (!user) {
    redirect("/login?next=%2Faccount%2Fprofile");
  }

  if (!user.email) {
    return {
      error: "Your sign-in account needs an email address to create a profile.",
    };
  }

  const { data: profile, error: profileError } = await supabase
    .from("guests")
    .select("id")
    .eq("auth_user_id", user.id)
    .maybeSingle();

  if (profileError) {
    return { error: getSaveError(profileError.code) };
  }

  const result = profile
    ? await supabase
        .from("guests")
        .update(values)
        .eq("auth_user_id", user.id)
        .select("id")
        .maybeSingle()
    : await supabase
        .from("guests")
        .insert({
          ...values,
          auth_user_id: user.id,
          email: user.email,
        })
        .select("id")
        .single();

  if (result.error) {
    return { error: getSaveError(result.error.code) };
  }

  if (!result.data) {
    return {
      error: "Your profile could not be found. Refresh the page and try again.",
    };
  }

  revalidatePath("/account/profile");
  revalidatePath("/account");
  redirect("/account/profile");
}import "server-only";

import { unstable_noStore } from "next/cache";
import { redirect } from "next/navigation";

import { isUnauthenticatedAuthError } from "@/lib/auth-errors";
import { createServerSupabaseClient } from "@/lib/supabase/server";

export async function getAccountGuest() {
  unstable_noStore();

  const supabase = await createServerSupabaseClient();
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError && isUnauthenticatedAuthError(authError)) {
    redirect("/login?next=%2Faccount");
  }

  if (authError) {
    throw authError;
  }

  if (!user) {
    redirect("/login?next=%2Faccount");
  }

  const { data: guest, error } = await supabase
    .from("guests")
    .select("id, fullName, email, nationality, nationalID, countryFlag")
    .eq("auth_user_id", user.id)
    .maybeSingle();

  if (error) {
    throw error;
  }

  return { guest, supabase };
}import { z } from "zod";

export const guestProfileSchema = z.object({
  fullName: z.string().trim().min(1).max(150),
  nationality: z.string().trim().min(1).max(100),
  nationalID: z.string().trim().min(1).max(100),
  countryFlag: z.string().trim().min(1).max(16),
});

export type GuestProfile = z.infer<typeof guestProfileSchema>;"use client";

import { useActionState, useMemo, useState } from "react";
import Link from "next/link";

import { createReservationAction } from "@/features/reservations/actions";
import type { ActionState } from "@/lib/action-state";
import type { Cabin } from "@/features/cabins/types";

const initialState: ActionState = {};

function getDefaultDates() {
  const start = new Date();
  start.setDate(start.getDate() + 3);

  const end = new Date(start);
  end.setDate(end.getDate() + 4);

  return {
    startDate: start.toISOString().slice(0, 10),
    endDate: end.toISOString().slice(0, 10),
  };
}

export default function CabinReservation({ cabin }: { cabin: Cabin }) {
  const defaultDates = useMemo(() => getDefaultDates(), []);
  const [state, formAction, pending] = useActionState(
    createReservationAction,
    initialState,
  );
  const [reservation, setReservation] = useState({
    startDate: defaultDates.startDate,
    endDate: defaultDates.endDate,
    guests: Math.min(cabin.maxCapacity, 2),
    notes: "",
  });
  const nights = useMemo(() => {
    const start = new Date(reservation.startDate);
    const end = new Date(reservation.endDate);

    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
      return 0;
    }

    const diffInMs = end.getTime() - start.getTime();
    return Math.max(Math.ceil(diffInMs / (1000 * 60 * 60 * 24)), 0);
  }, [reservation.startDate, reservation.endDate]);

  const discountedPrice = Math.max(cabin.regularPrice - cabin.discount, 0);
  const totalPrice = nights > 0 ? nights * discountedPrice : 0;

  const guestOptions = useMemo(() => {
    return Array.from({ length: cabin.maxCapacity }, (_, index) => index + 1);
  }, [cabin.maxCapacity]);

  const today = new Date().toISOString().slice(0, 10);
  const checkoutMinimum =
    reservation.startDate &&
    !Number.isNaN(Date.parse(`${reservation.startDate}T00:00:00Z`))
      ? new Date(
          Date.parse(`${reservation.startDate}T00:00:00Z`) + 86_400_000,
        )
          .toISOString()
          .slice(0, 10)
      : today;

  return (
    <aside className="border border-primary-800 bg-primary-900/50 p-5">
      <p className="text-sm font-medium text-primary-400">Price per night</p>

      <div className="mt-2 flex items-baseline gap-2">
        <span className="text-3xl font-semibold text-primary-50">
          ${discountedPrice}
        </span>
        <span className="text-sm text-primary-400">/ night</span>
      </div>

      {cabin.discount > 0 && (
        <p className="mt-2 text-sm text-primary-400">
          Regular price: <span className="line-through">${cabin.regularPrice}</span>
        </p>
      )}

      <form action={formAction} className="mt-6 space-y-4">
        <input type="hidden" name="cabinId" value={cabin.id} />

        <div className="grid gap-4 sm:grid-cols-2">
          <label className="block text-sm text-primary-200">
            <span className="mb-1 block text-xs uppercase tracking-wide text-primary-400">
              Check-in
            </span>
            <input
              type="date"
              name="startDate"
              min={today}
              required
              value={reservation.startDate}
              onChange={(event) =>
                setReservation((current) => ({
                  ...current,
                  startDate: event.target.value,
                }))
              }
              className="w-full border border-primary-700 bg-primary-900 px-3 py-2 text-primary-100 outline-none transition-colors focus:border-accent-500"
            />
          </label>

          <label className="block text-sm text-primary-200">
            <span className="mb-1 block text-xs uppercase tracking-wide text-primary-400">
              Check-out
            </span>
            <input
              type="date"
              name="endDate"
              min={checkoutMinimum}
              required
              value={reservation.endDate}
              onChange={(event) =>
                setReservation((current) => ({
                  ...current,
                  endDate: event.target.value,
                }))
              }
              className="w-full border border-primary-700 bg-primary-900 px-3 py-2 text-primary-100 outline-none transition-colors focus:border-accent-500"
            />
          </label>
        </div>

        <label className="block text-sm text-primary-200">
          <span className="mb-1 block text-xs uppercase tracking-wide text-primary-400">
            Guests
          </span>
          <select
            name="numGuests"
            value={reservation.guests}
            onChange={(event) =>
              setReservation((current) => ({
                ...current,
                guests: Number(event.target.value),
              }))
            }
            className="w-full border border-primary-700 bg-primary-900 px-3 py-2 text-primary-100 outline-none transition-colors focus:border-accent-500"
          >
            {guestOptions.map((option) => (
              <option key={option} value={option}>
                {option} {option === 1 ? "guest" : "guests"}
              </option>
            ))}
          </select>
        </label>

        <label className="block text-sm text-primary-200">
          <span className="mb-1 block text-xs uppercase tracking-wide text-primary-400">
            Notes
          </span>
          <textarea
            name="observations"
            value={reservation.notes}
            maxLength={500}
            onChange={(event) =>
              setReservation((current) => ({
                ...current,
                notes: event.target.value,
              }))
            }
            rows={3}
            className="w-full resize-none border border-primary-700 bg-primary-900 px-3 py-2 text-primary-100 outline-none transition-colors focus:border-accent-500"
            placeholder="Anything we should know?"
          />
        </label>

        <div className="border border-primary-700 bg-primary-950 p-3 text-sm text-primary-200">
          <div className="flex items-center justify-between gap-2">
            <span>{nights} nights</span>
            <span>${totalPrice}</span>
          </div>
        </div>

        <button
          type="submit"
          disabled={pending || Boolean(state.message)}
          className="w-full bg-accent-500 px-4 py-2.5 text-sm font-semibold text-primary-900 transition-colors hover:bg-accent-600 disabled:cursor-wait disabled:opacity-60"
        >
          {pending
            ? "Submitting..."
            : state.message
              ? "Reservation submitted"
              : "Reserve cabin"}
        </button>

        {state.error ? (
          <p role="alert" className="text-sm text-red-300">
            {state.error}
            {state.error ===
              "Complete your guest profile before reserving a cabin." && (
              <>
                {" "}
                <Link
                  href="/account/profile"
                  className="underline underline-offset-4"
                >
                  Complete your profile
                </Link>
              </>
            )}
          </p>
        ) : state.message ? (
          <p role="status" aria-live="polite" className="text-sm text-accent-400">
            {state.message}{" "}
            <Link
              href="/account/reservations"
              className="underline underline-offset-4"
            >
              View reservations
            </Link>
          </p>
        ) : null}
      </form>
    </aside>
  );
}"use server";

import { updateTag, revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

import { isUnauthenticatedAuthError } from "@/lib/auth-errors";
import type { ActionState } from "@/lib/action-state";
import { createServerSupabaseClient } from "@/lib/supabase/server";
import { reservationSchema } from "./schemas";

function getReservationSaveError(code: string | undefined): string {
  if (code === "42501") {
    return "Reservation creation is unavailable until the reservation permissions migration has been applied.";
  }

  return "We couldn't create this reservation. Please try again.";
}

export async function createReservationAction(
  _previousState: ActionState,
  formData: FormData,
): Promise<ActionState> {
  const result = reservationSchema.safeParse({
    cabinId: formData.get("cabinId"),
    startDate: formData.get("startDate"),
    endDate: formData.get("endDate"),
    numGuests: formData.get("numGuests"),
    observations: formData.get("observations"),
  });

  if (!result.success) {
    return { error: "Enter valid reservation details and try again." };
  }

  const input = result.data;
  const supabase = await createServerSupabaseClient();
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser();

  if (authError && isUnauthenticatedAuthError(authError)) {
    redirect(`/login?next=${encodeURIComponent(`/cabins/${input.cabinId}`)}`);
  }

  if (authError) {
    return { error: "We couldn't verify your sign-in. Please try again." };
  }

  if (!user) {
    redirect(`/login?next=${encodeURIComponent(`/cabins/${input.cabinId}`)}`);
  }

  const { data: guest, error: guestError } = await supabase
    .from("guests")
    .select("id")
    .eq("auth_user_id", user.id)
    .maybeSingle();

  if (guestError) {
    return { error: "We couldn't verify your guest profile. Please try again." };
  }

  if (!guest) {
    return {
      error: "Complete your guest profile before reserving a cabin.",
    };
  }

  const { data: cabin, error: cabinError } = await supabase
    .from("cabins")
    .select("regularPrice, discount, maxCapacity")
    .eq("id", input.cabinId)
    .maybeSingle();

  if (cabinError) {
    return { error: "We couldn't verify this cabin. Please try again." };
  }

  if (!cabin) {
    return { error: "This cabin is no longer available." };
  }

  if (
    !Number.isSafeInteger(input.numGuests) ||
    input.numGuests < 1 ||
    input.numGuests > cabin.maxCapacity
  ) {
    return { error: "Choose a guest count within this cabin's capacity." };
  }

  const nightlyRate = Math.max(cabin.regularPrice - cabin.discount, 0);

  if (!Number.isFinite(nightlyRate) || nightlyRate < 0) {
    return { error: "We couldn't calculate this cabin's price." };
  }

  const numNights =
    (Date.parse(`${input.endDate}T00:00:00Z`) -
      Date.parse(`${input.startDate}T00:00:00Z`)) /
    86_400_000;
  const totalPrice = nightlyRate * numNights;

  if (
    !Number.isSafeInteger(numNights) ||
    !Number.isSafeInteger(totalPrice)
  ) {
    return { error: "Choose valid reservation dates and try again." };
  }

  const { data: isAvailable, error: availabilityError } = await supabase.rpc(
    "is_booking_available",
    {
      p_cabin_id: input.cabinId,
      p_start_date: input.startDate,
      p_end_date: input.endDate,
    },
  );

  if (availabilityError) {
    return {
      error:
        "We couldn't verify cabin availability. Please try again later.",
    };
  }

  if (isAvailable !== true) {
    return {
      error: "This cabin is already reserved for some of those dates.",
    };
  }

  const { error: insertError } = await supabase.from("bookings").insert({
    cabinId: input.cabinId,
    guestId: guest.id,
    cabinPrice: nightlyRate,
    startDate: `${input.startDate}T00:00:00.000Z`,
    endDate: `${input.endDate}T00:00:00.000Z`,
    numGuests: input.numGuests,
    numNights,
    totalPrice,
    status: "unconfirmed",
    isPaid: false,
    observations: input.observations,
  });

  if (insertError) {
    return { error: getReservationSaveError(insertError.code) };
  }

  updateTag("cabins");
  updateTag(`cabin-${input.cabinId}`);
  revalidatePath(`/cabins/${input.cabinId}`);
  revalidatePath("/account/reservations");

  return { message: "Your reservation has been submitted." };
}import "server-only";

import { getAccountGuest } from "@/features/profile/queries";

export async function getAccountReservations() {
  const { guest, supabase } = await getAccountGuest();

  if (!guest) {
    return { guest, reservations: [] };
  }

  const { data: bookings, error: bookingsError } = await supabase
    .from("bookings")
    .select(
      "id, startDate, endDate, numGuests, numNights, totalPrice, status, cabinId",
    )
    .eq("guestId", guest.id)
    .order("startDate", { ascending: false });

  if (bookingsError) {
    throw bookingsError;
  }

  const cabinIds = [...new Set(bookings.map((booking) => booking.cabinId))];
  const { data: cabins, error: cabinsError } = cabinIds.length
    ? await supabase
        .from("cabins")
        .select("id, cabin_number")
        .in("id", cabinIds)
    : { data: [], error: null };

  if (cabinsError) {
    throw cabinsError;
  }

  const cabinNumbers = new Map(
    cabins.map((cabin) => [cabin.id, cabin.cabin_number]),
  );

  return {
    guest,
    reservations: bookings.map((booking) => ({
      ...booking,
      cabinNumber: cabinNumbers.get(booking.cabinId),
    })),
  };
}import { z } from "zod";

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

function isCalendarDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);

  if (!match) {
    return false;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (year < 1 || month < 1 || month > 12) {
    return false;
  }

  const isLeapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [
    31,
    isLeapYear ? 29 : 28,
    31,
    30,
    31,
    30,
    31,
    31,
    30,
    31,
    30,
    31,
  ];

  return day >= 1 && day <= daysInMonth[month - 1];
}

const reservationDateSchema = z
  .string()
  .regex(DATE_PATTERN)
  .refine(isCalendarDate);

export const reservationSchema = z
  .object({
    cabinId: z.string().uuid(),
    startDate: reservationDateSchema,
    endDate: reservationDateSchema,
    numGuests: z
      .string()
      .regex(/^[1-9]\d*$/)
      .transform(Number)
      .refine((numGuests) => Number.isSafeInteger(numGuests)),
    observations: z.string().trim().max(500),
  })
  .refine(
    ({ startDate }) => startDate >= new Date().toISOString().slice(0, 10),
    { path: ["startDate"] },
  )
  .refine(({ startDate, endDate }) => endDate > startDate, {
    path: ["endDate"],
  });"use client";

