import { createServerClient, type CookieMethodsServer } from "@supabase/ssr";
import { cookies } from "next/headers";

import { getSupabaseConfig } from "./config";

async function getNextCookieMethods(): Promise<CookieMethodsServer> {
  const cookieStore = await cookies();

  return {
    getAll() {
      return cookieStore.getAll();
    },
    setAll(cookiesToSet) {
      try {
        for (const { name, value, options } of cookiesToSet) {
          cookieStore.set(name, value, options);
        }
      } catch {
        // proxy.ts refreshes sessions, so Server Component cookie writes are safe to ignore.
      }
    },
  };
}

export async function createServerSupabaseClient(
  cookieMethods?: CookieMethodsServer,
) {
  const { supabaseUrl, supabasePublishableKey } = getSupabaseConfig();

  return createServerClient(supabaseUrl, supabasePublishableKey, {
    cookies: cookieMethods ?? (await getNextCookieMethods()),
  });
}export type ActionState = {
  error?: string;
  message?: string;
};import { isAuthApiError } from "@supabase/supabase-js";

export function isUnauthenticatedAuthError(error: unknown): boolean {
  if (
    error instanceof Error &&
    (error.name === "AuthSessionMissingError" ||
      error.name === "AuthUserMissingError")
  ) {
    return true;
  }

  return isAuthApiError(error) && (error.status === 401 || error.status === 403);
}function getHttpOrigin(value: string | null | undefined): string | null {
  if (!value) {
    return null;
  }

  try {
    const url = new URL(value);

    if (
      (url.protocol !== "http:" && url.protocol !== "https:") ||
      !url.hostname ||
      url.username ||
      url.password
    ) {
      return null;
    }

    return url.origin;
  } catch {
    return null;
  }
}

export function getTrustedSiteOrigin(requestOrigin?: string | null) {
  return (
    getHttpOrigin(process.env.NEXT_PUBLIC_SITE_URL) ??
    getHttpOrigin(requestOrigin)
  );
}-- DRAFT FOR REVIEW ONLY. This is a one-shot security migration for the
